CREATE TABLE samples(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, product_id uuid NOT NULL REFERENCES products, quantity numeric(20,6) NOT NULL CHECK(quantity>0), purpose text NOT NULL, status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','approved','shipped','received','validated','rejected')), source_id uuid REFERENCES sources, feedback text NOT NULL DEFAULT '');
CREATE TABLE aftersales(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, order_id uuid NOT NULL REFERENCES orders, product_id uuid NOT NULL REFERENCES products, batch text NOT NULL, problem text NOT NULL, source_id uuid NOT NULL REFERENCES sources, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','investigating','pending_approval','approved','closed')), resolution text NOT NULL DEFAULT '', compensation numeric(20,6) NOT NULL DEFAULT 0 CHECK(compensation>=0), approved_by uuid REFERENCES users, customer_feedback text NOT NULL DEFAULT '');
CREATE TABLE trade_documents(LIKE records_base INCLUDING ALL, order_id uuid NOT NULL REFERENCES orders, kind text NOT NULL CHECK(kind IN('pi','invoice','packing_list')), revision integer NOT NULL, template_version text NOT NULL DEFAULT 'v1', status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','corrected')), snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, approved_by uuid REFERENCES users, UNIQUE(order_id,kind,revision));
CREATE TABLE allocation_reversals(LIKE records_base INCLUDING ALL, allocation_id uuid NOT NULL UNIQUE REFERENCES allocations, reason text NOT NULL);
CREATE TABLE account_relationships(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, name text NOT NULL, kind text NOT NULL CHECK(kind IN('branch','warehouse','distributor','buying_role')), location text NOT NULL DEFAULT '', fact_status text NOT NULL DEFAULT 'extracted' CHECK(fact_status IN('unknown','extracted','confirmed','conflicted')), source_id uuid NOT NULL REFERENCES sources);
CREATE TABLE development_plans(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, market_revision_id uuid NOT NULL REFERENCES market_revisions, proposal text NOT NULL, unknowns text NOT NULL DEFAULT '', next_steps text NOT NULL, knowledge_ids uuid[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'proposal');
CREATE TABLE knowledge_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), knowledge_id uuid NOT NULL REFERENCES knowledge, revision integer NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(knowledge_id,revision));
CREATE TABLE automation_rules(LIKE records_base INCLUDING ALL, name text NOT NULL, version integer NOT NULL DEFAULT 1, kind text NOT NULL CHECK(kind IN('internal_followup','internal_review')), enabled boolean NOT NULL DEFAULT false, daily_limit integer NOT NULL CHECK(daily_limit>0 AND daily_limit<=2000), scope_activity_id uuid REFERENCES activities, stop_reason text);
CREATE TABLE action_executions(LIKE records_base INCLUDING ALL, rule_id uuid NOT NULL REFERENCES automation_rules, task_id uuid REFERENCES tasks, idempotency_key text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN('succeeded','cancelled','failed','outcome_unknown')), error text);
CREATE TABLE eval_datasets(LIKE records_base INCLUDING ALL, name text NOT NULL, revision integer NOT NULL DEFAULT 1, fixture_type text NOT NULL CHECK(fixture_type IN('synthetic','anonymized')), adjudicator text NOT NULL, cases jsonb NOT NULL, UNIQUE(business_entity_id,name,revision));
CREATE TABLE eval_runs(LIKE records_base INCLUDING ALL, dataset_id uuid NOT NULL REFERENCES eval_datasets, config_version text NOT NULL, code_version text NOT NULL, status text NOT NULL CHECK(status IN('passed','failed','pending_adjudication')), results jsonb NOT NULL);
CREATE TABLE release_gates(LIKE records_base INCLUDING ALL, eval_run_id uuid NOT NULL REFERENCES eval_runs, stage text NOT NULL CHECK(stage IN('A','B','C')), status text NOT NULL CHECK(status IN('released','rolled_back')), reason text NOT NULL);
CREATE UNIQUE INDEX one_selected_response ON supplier_responses(purchase_rfq_id,rfq_line_id) WHERE selected;
CREATE TABLE rate_limits(key text PRIMARY KEY, count integer NOT NULL, window_at timestamptz NOT NULL);
ALTER TABLE opportunities ADD COLUMN confirmed_order_id uuid REFERENCES orders;
ALTER TABLE accounts ADD COLUMN archived_at timestamptz;
ALTER TABLE accounts ADD COLUMN archive_reason text;
CREATE TABLE payment_policy(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL UNIQUE REFERENCES accounts, mode text NOT NULL CHECK(mode IN('warn_only','prepaid','credit')), min_prepaid_ratio numeric(10,6) NOT NULL CHECK(min_prepaid_ratio>=0 AND min_prepaid_ratio<=1), source_id uuid NOT NULL REFERENCES sources);
